new file mode 100644
index 0000000..4008b18
--- /dev/null
+++ b/src/options.c
@@ -0,0 +1,174 @@
+#include "options.h"
+#include "error.h"
+#include "manpage.h"
+
+void options_init(Options *opts) {
+    opts->async = 0;
+    opts->bold = 0;
+    opts->all_bold = 0;
+    opts->force_term = 0;
+    opts->linux_mode = 0;
+    opts->old_scroll = 0;
+    opts->shadows = 0;
+    opts->locked = 0;
+    opts->rainbow = 0;
+    opts->lambda_mode = 0;
+    opts->char_change = 0;
+    opts->screensaver = 0;
+    opts->x_mode = 0;
+    opts->no_bold = 0;
+    opts->help = 0;
+    opts->version = 0;
+    opts->use_japanese = 0;
+    opts->delay = DEFAULT_DELAY;
+    opts->color = COLOR_GREEN;
+    opts->message = NULL;
+    opts->tty = NULL;
+}
+
+int options_parse(int argc, char **argv, Options *opts) {
+    int i = 1;
+    while (i < argc) {
+        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
+            opts->help = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-V") == 0) {
+            opts->version = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-a") == 0) {
+            opts->async = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-b") == 0) {
+            opts->bold = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-B") == 0) {
+            opts->all_bold = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-c") == 0) {
+            opts->use_japanese = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-f") == 0) {
+            opts->force_term = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-l") == 0) {
+            opts->linux_mode = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-L") == 0) {
+            opts->locked = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-o") == 0) {
+            opts->old_scroll = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-n") == 0) {
+            opts->no_bold = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-s") == 0) {
+            opts->screensaver = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-x") == 0) {
+            opts->x_mode = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-r") == 0) {
+            opts->rainbow = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-m") == 0) {
+            opts->lambda_mode = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-k") == 0) {
+            opts->char_change = 1;
+            i++;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-u") == 0) {
+            if (i + 1 >= argc) {
+                error_exit("Error: -u requires a delay value", 1);
+            }
+            opts->delay = atoi(argv[i + 1]);
+            if (opts->delay < MIN_DELAY || opts->delay > MAX_DELAY) {
+                fprintf(stderr, "Error: delay must be between %d and %d\n", MIN_DELAY, MAX_DELAY);
+                return -1;
+            }
+            i += 2;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-C") == 0) {
+            if (i + 1 >= argc) {
+                error_exit("Error: -C requires a color value", 1);
+            }
+            opts->color = validate_color(argv[i + 1]);
+            i += 2;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-M") == 0) {
+            if (i + 1 >= argc) {
+                error_exit("Error: -M requires a message", 1);
+            }
+            opts->message = argv[i + 1];
+            i += 2;
+            continue;
+        }
+        
+        if (strcmp(argv[i], "-t") == 0) {
+            if (i + 1 >= argc) {
+                error_exit("Error: -t requires a tty value", 1);
+            }
+            opts->tty = argv[i + 1];
+            i += 2;
+            continue;
+        }
+        
+        // Unknown option
+        fprintf(stderr, "Error: unknown option '%s'\n", argv[i]);
+        return -1;
+    }
+    
+    return 0;
+}
diff --git a/src/options.h b/src/options.h
new file mode 100644
index 0000000..e32f67f
--- /dev/null
+++ b/src/options.h
@@ -0,0 +1,74 @@
+#ifndef OPTIONS_H
+#define OPTIONS_H
+
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <unistd.h>
+#include <termios.h>
+#include <sys/select.h>
+#include <sys/time.h>
+#include <sys/ioctl.h>
+#include <signal.h>
+#include <time.h>
+#include <ctype.h>
+
+#define VERSION "2.0"
+#define BUILD_TIME "22:13:51, Jun 11 2026"
+#define EMAIL "abishekvashok@gmail.com"
+#define WEB "https://github.com/abishekvashok/cmatrix"
+
+#define DEFAULT_DELAY 4
+#define MIN_DELAY 0
+#define MAX_DELAY 10
+
+#define DEFAULT_COLOR "green"
+
+typedef enum {
+    COLOR_GREEN,
+    COLOR_RED,
+    COLOR_BLUE,
+    COLOR_WHITE,
+    COLOR_YELLOW,
+    COLOR_CYAN,
+    COLOR_MAGENTA,
+    COLOR_BLACK
+} Color;
+
+typedef struct {
+    int async;           // -a: Asynchronous scroll
+    int bold;            // -b: Bold characters on
+    int all_bold;        // -B: All bold characters
+    int force_term;      // -f: Force linux $TERM type
+    int linux_mode;      // -l: Linux mode
+    int old_scroll;      // -o: Old-style scrolling
+    int shadows;         // -c: Only print shadows
+    int locked;          // -L: Lock mode
+    int rainbow;         // -r: Rainbow mode
+    int lambda_mode;     // -m: Lambda mode
+    int char_change;     // -k: Characters change
+    int screensaver;     // -s: Screensaver mode
+    int x_mode;          // -x: X window mode
+    int no_bold;         // -n: No bold characters
+    int help;            // -h, -?: Print usage
+    int version;         // -V: Print version
+    int use_japanese;    // -c: Use Japanese characters
+    int delay;           // -u: Screen update delay
+    Color color;         // -C: Color
+    char *message;       // -M: Message
+    char *tty;           // -t: TTY
+} Options;
+
+// Initialize options with defaults
+void options_init(Options *opts);
+
+// Parse command line arguments
+int options_parse(int argc, char **argv, Options *opts);
+
+// Print usage information
+void print_usage(const char *prog_name);
+
+// Print version information
+void print_version(void);
+
+#endif /* OPTIONS_H */
diff --git a/src/screen.c b/src/screen.c
new file mode 100644
index 0000000..0a6a9f2
--- /dev/null
+++ b/src/screen.c
@@ -0,0 +1,191 @@
+#include "screen.h"
+#include "options.h"
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <unistd.h>
+#include <time.h>
+#include <wchar.h>
+
+#define MATRIX_CHARS "アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
+#define MATRIX_CHARS_LEN (sizeof(MATRIX_CHARS) - 1)
+
+#define LAMBDA_CHARS "λλ"
+#define LAMBDA_CHARS_LEN (sizeof(LAMBDA_CHARS) - 1)
+
+#define JAPANESE_CHARS "アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン"
+#define JAPANESE_CHARS_LEN (sizeof(JAPANESE_CHARS) - 1)
+
+typedef struct {
+    wchar_t **lines;
+    int rows;
+    int cols;
+    int *offsets;
+    int *x_positions;
+    int *y_positions;
+    int *directions;
+    int *speeds;
+    int *colors;
+    int *bold;
+    int initialized;
+} screen_t;
+
+static screen_t *screen = NULL;
+
+static void screen_free(void);
+static void screen_init_internal(int rows, int cols, Options *opts);
+static void screen_update_internal(Options *opts);
+static void screen_clear_internal(void);
+static void screen_print_char_internal(int row, int col, wchar_t ch, int bold, int color);
+
+static void screen_free(void) {
+    if (screen) {
+        for (int i = 0; i < screen->rows; i++) {
+            free(screen->lines[i]);
+        }
+        free(screen->lines);
+        free(screen->offsets);
+        free(screen->x_positions);
+        free(screen->y_positions);
+        free(screen->directions);
+        free(screen->speeds);
+        free(screen->colors);
+        free(screen->bold);
+        free(screen);
+    }
+}
+
+static void screen_init_internal(int rows, int cols, Options *opts) {
+    (void)opts;
+    screen = calloc(1, sizeof(screen_t));
+    if (!screen) {
+        return;
+    }
+    screen->rows = rows;
+    screen->cols = cols;
+    screen->lines = calloc(rows, sizeof(wchar_t *));
+    screen->offsets = calloc(rows, sizeof(int));
+    screen->x_positions = calloc(rows * cols, sizeof(int));
+    screen->y_positions = calloc(rows * cols, sizeof(int));
+    screen->directions = calloc(rows * cols, sizeof(int));
+    screen->speeds = calloc(rows * cols, sizeof(int));
+    screen->colors = calloc(rows * cols, sizeof(int));
+    screen->bold = calloc(rows * cols, sizeof(int));
+    screen->initialized = 0;
+    if (!screen->lines || !screen->offsets || !screen->x_positions || 
+        !screen->y_positions || !screen->directions || !screen->speeds ||
+        !screen->colors || !screen->bold) {
+        screen_free();
+        return;
+    }
+    for (int i = 0; i < rows; i++) {
+        screen->lines[i] = calloc(cols, sizeof(wchar_t));
+    }
+    for (int i = 0; i < rows; i++) {
+        screen->offsets[i] = 0;
+        for (int j = 0; j < cols; j++) {
+            screen->x_positions[i * cols + j] = j;
+            screen->y_positions[i * cols + j] = i;
+            screen->directions[i * cols + j] = 1;
+            screen->speeds[i * cols + j] = 1;
+            screen->colors[i * cols + j] = 0;
+            screen->bold[i * cols + j] = 0;
+        }
+    }
+    screen->initialized = 1;
+}
+
+void screen_init(int rows, int cols, Options *opts) {
+    screen_init_internal(rows, cols, opts);
+}
+
+static void screen_update_internal(Options *opts) {
+    if (!screen || !screen->initialized) return;
+    for (int i = 0; i < screen->rows; i++) {
+        screen->offsets[i] += opts->delay;
+        if (screen->offsets[i] >= screen->cols) {
+            screen->offsets[i] = 0;
+        }
+        for (int j = 0; j < screen->cols; j++) {
+            int idx = i * screen->cols + j;
+            int new_x = screen->x_positions[idx] + screen->directions[idx] * screen->speeds[idx];
+            if (new_x >= screen->cols) {
+                new_x = 0;
+                screen->directions[idx] = 1;
+            } else if (new_x < 0) {
+                new_x = screen->cols - 1;
+                screen->directions[idx] = -1;
+            }
+            screen->x_positions[idx] = new_x;
+        }
+    }
+    for (int i = 0; i < screen->rows; i++) {
+        for (int j = 0; j < screen->cols; j++) {
+            int idx = i * screen->cols + j;
+            int x = screen->x_positions[idx];
+            wchar_t ch;
+            if (opts->lambda_mode) {
+                ch = LAMBDA_CHARS[rand() % LAMBDA_CHARS_LEN];
+            } else if (opts->use_japanese) {
+                ch = JAPANESE_CHARS[rand() % JAPANESE_CHARS_LEN];
+            } else {
+                ch = MATRIX_CHARS[rand() % MATRIX_CHARS_LEN];
+            }
+            int color = opts->color;
+            if (opts->rainbow) {
+                color = (i + j) % 8;
+            }
+            int bold = opts->bold;
+            if (opts->all_bold) {
+                bold = 1;
+            } else if (opts->no_bold) {
+                bold = 0;
+            }
+            screen->colors[idx] = color;
+            screen->bold[idx] = bold;
+            screen_print_char_internal(i, x, ch, bold, color);
+        }
+    }
+}
+
+void screen_update(Options *opts) {
+    screen_update_internal(opts);
+}
+
+static void screen_clear_internal(void) {
+    if (!screen || !screen->initialized) return;
+    for (int i = 0; i < screen->rows; i++) {
+        for (int j = 0; j < screen->cols; j++) {
+            screen_print_char_internal(i, j, L' ', 0, 0);
+        }
+    }
+}
+
+void screen_clear(void) {
+    screen_clear_internal();
+}
+
+static void screen_print_char_internal(int row, int col, wchar_t ch, int bold, int color) {
+    if (row < 0 || row >= screen->rows || col < 0 || col >= screen->cols) return;
+    if (color >= 0 && color <= 7) {
+        if (color == 0) { printf("\033[32m"); }
+        else if (color == 1) { printf("\033[31m"); }
+        else if (color == 2) { printf("\033[34m"); }
+        else if (color == 3) { printf("\033[37m"); }
+        else if (color == 4) { printf("\033[33m"); }
+        else if (color == 5) { printf("\033[36m"); }
+        else if (color == 6) { printf("\033[35m"); }
+        else if (color == 7) { printf("\033[30m"); }
+    }
+    if (bold) { printf("\033[1m"); }
+    wprintf(L"%lc", ch);
+    printf("\033[0m");
+}
+
+void screen_print_line(int row, const wchar_t *line, int len) {
+    if (!screen || !screen->initialized) return;
+    for (int i = 0; i < len && row >= 0 && row < screen->rows; i++) {
+        int col = i;
+        screen_print_char_internal(row, col, line[i], 0, 0);
+    }
+}
